function configuredSender(value) {
  const address = typeof value === "string" ? value.trim().toLowerCase() : "";
  if (!/^[^@\s<>']+@[^@\s<>']+\.[^@\s<>']+$/.test(address) || address.endsWith(".invalid")) {
    throw new Error("Set the exact sender email address before enabling the workflow.");
  }
  return address;
}

function messageKey(value) {
  return typeof value === "string" && /^[A-Za-z0-9_+/=-]{1,512}$/.test(value);
}

function mailCandidates(events, sender) {
  const ids = new Set();
  const messages = [];
  for (const event of events) {
    if (
      event.isDraft !== false ||
      typeof event.from !== "string" ||
      event.from.trim().toLowerCase() !== sender
    )
      continue;
    const { messageId, conversationId } = event;
    if (!messageKey(messageId) || !messageKey(conversationId))
      throw new Error("Outlook did not identify the triggering email and thread.");
    if (!ids.has(messageId)) messages.push({ messageId, conversationId });
    ids.add(messageId);
  }
  return messages;
}

const settings = { sender: "YOUR_SENDER@example.invalid", voice: "" };
const address = configuredSender(settings.sender);
const events = $input.all().map(({ json }) => ({
  messageId: json.id,
  conversationId: json.conversationId,
  from: json.from?.emailAddress?.address,
  isDraft: json.isDraft,
}));
return mailCandidates(events, address).map((message) => ({
  json: {
    ...message,
    sender: address,
    voice: settings.voice,
    key: "outlook-reply:" + message.messageId,
  },
  pairedItem: { item: events.findIndex((event) => event.messageId === message.messageId) },
}));

function replyInput(message, event, sender, voice) {
  if (
    message?.id !== event.messageId ||
    message.conversationId !== event.conversationId ||
    message.from?.emailAddress?.address?.trim().toLowerCase() !== sender ||
    message.isDraft !== false
  ) {
    throw new Error("Outlook returned a different message, sender, or thread.");
  }
  if (typeof voice !== "string" || voice.length > 4000)
    throw new Error("Keep voice examples within 4,000 characters.");
  const text = message.uniqueBody?.content;
  if (
    String(message.uniqueBody?.contentType).toLowerCase() !== "text" ||
    typeof text !== "string" ||
    !text.trim() ||
    text.length > 12000 ||
    typeof message.subject !== "string" ||
    message.subject.length > 1000
  ) {
    throw new Error(
      "The current email must have a readable, nonempty unique text body and a valid subject.",
    );
  }
  return JSON.stringify({
    from: sender,
    subject: message.subject,
    currentMessage: text,
    ...(voice.trim() ? { voiceExamples: voice } : {}),
  });
}

const original = $("Keep the triggering message ID").itemMatching(0).json;
const { body, statusCode } = $input.first().json;
if (statusCode !== 200) throw Error("Outlook did not confirm the triggering email.");
return [
  {
    json: { original, input: replyInput(body, original, original.sender, original.voice) },
    pairedItem: { item: 0 },
  },
];

function replyBody(response) {
  const messages = response?.output?.filter((entry) => entry.type === "message");
  const message = messages?.[0];
  const content = message?.content?.[0];
  if (
    response?.status !== "completed" ||
    messages?.length !== 1 ||
    message.role !== "assistant" ||
    message.status !== "completed" ||
    message.content.length !== 1 ||
    content?.type !== "output_text"
  ) {
    throw new Error("OpenAI did not return a completed reply draft.");
  }
  const fields = JSON.parse(content.text);
  const reply = typeof fields?.reply === "string" ? fields.reply.trim() : "";
  if (
    !reply ||
    reply.length > 1800 ||
    Object.keys(fields).length !== 1 ||
    /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/u.test(reply)
  ) {
    throw new Error("The model reply must be a single plain-text draft of up to 1,800 characters.");
  }
  return { message: { body: { contentType: "Text", content: reply } } };
}

const { original } = $("Prepare the current email only").itemMatching(0).json;
const { body, statusCode } = $input.first().json;
if (statusCode !== 200) throw Error("OpenAI did not confirm the reply.");
return [{ json: { original, request: replyBody(body) }, pairedItem: { item: 0 } }];

function messageKey(value) {
  return typeof value === "string" && /^[A-Za-z0-9_+/=-]{1,512}$/.test(value);
}

function confirmDraft(status, draft, original) {
  if (
    status !== 201 ||
    !messageKey(draft?.id) ||
    draft.id === original.messageId ||
    draft.isDraft !== true ||
    draft.conversationId !== original.conversationId
  ) {
    throw new Error(
      "Outlook did not confirm a draft on this thread. Check Drafts before repeating.",
    );
  }
  return {
    messageId: original.messageId,
    conversationId: original.conversationId,
    draftId: draft.id,
    isDraft: true,
  };
}

const { body, statusCode } = $input.first().json;
const { original } = $("Prepare the threaded reply").itemMatching(0).json;
return [{ json: confirmDraft(statusCode, body, original), pairedItem: { item: 0 } }];
